import "server-only";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { env } from "@/lib/env";

/** Where photo bytes live. The database holds only the key. */
export interface PhotoStorage {
  put(key: string, bytes: Uint8Array): Promise<void>;
  get(key: string): Promise<Buffer | null>;
}

/** Keys are generated by the server: `<orderId>/<cuid>.<ext>`. Anything else is refused. */
const KEY_PATTERN = /^[a-z0-9]+\/[a-z0-9]+\.(jpg|png|webp)$/;

function localStorage(root: string): PhotoStorage {
  const resolve = (key: string) => {
    if (!KEY_PATTERN.test(key)) throw new Error(`Invalid storage key: ${key}`);
    return path.join(root, key);
  };
  return {
    async put(key, bytes) {
      const file = resolve(key);
      await mkdir(path.dirname(file), { recursive: true });
      await writeFile(file, bytes);
    },
    async get(key) {
      try {
        return await readFile(resolve(key));
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
        throw error;
      }
    },
  };
}

let storage: PhotoStorage | undefined;

export function photoStorage(): PhotoStorage {
  storage ??= localStorage(path.resolve(env.STORAGE_LOCAL_DIR));
  return storage;
}
